@users_bp.route("/filter", methods=["GET"])
@require_role("manager")
def filter_users():
    """Filter users by field=value query parameters."""
    clauses = []
    for field, value in request.args.items():
        clauses.append(f"{field} = '{value}'")
    where = " AND ".join(clauses) or "1=1"
    session = get_session()
    rows = session.execute(
        text("SELECT id, username, role FROM users WHERE " + where)
    )
    return jsonify([dict(r._mapping) for r in rows])

findings.suggested_fix:
Do not interpolate request values into the SQL string. (1) Validate the field name against a hard-coded allowlist of permitted columns (e.g. {"id", "username", "role"}) and reject anything else. (2) Use bound parameters for the value: build `text("SELECT id, username, role FROM users WHERE " + where)` where `where` is composed of `:p0 AND :p1 ...` placeholders, and pass the values via `session.execute(stmt, {"p0": value0, ...})`. Example:

    ALLOWED = {"id", "username", "role"}
    clauses, params = [], {}
    for i, (field, value) in enumerate(request.args.items()):
        if field not in ALLOWED:
            return jsonify({"error": "invalid field"}), 400
        clauses.append(f"{field} = :p{i}")
        params[f"p{i}"] = value
    where = " AND ".join(clauses) or "1=1"
    stmt = text(f"SELECT id, username, role FROM users WHERE {where}")
    rows = session.execute(stmt, params)

This keeps the column name from a trusted allowlist and binds all user-supplied values as parameters, satisfying security-policy.md §5.

